"""Unit preconditions for telling a crash from a failure.

Covers `MQC_CMN_UNI_112385`, inventoried in ``docs/design/cmn_verdict_and_cli.md``
section 10. A failure here is **not a model finding**, so the module carries no
priority marker, per ``framework-rules.md`` section 3.3.
"""

# ------------------------------------------------------------- cases in here
# Generated by `tools/refresh_case_summaries.py`.
#
# TestMQCBroken
#   112385  a_case_that_crashes_is_broken_and_the_run_exits_3
# ------------------------------------------------------------ end of cases

import subprocess
import sys
from pathlib import Path

import allure
import pytest

pytestmark = pytest.mark.unit

_ROOT = Path(__file__).resolve().parents[2]

# A SESSION WIRED THE WAY BOTH REPOSITORIES WIRE THEIRS, so the case runs real
# pytest reports through the real classification rather than imitations of them.
_CONFTEST = '''
from typing import Any

import pytest

from cmn.band_summary import Alarms, result_lines, skipped_cases_from
from cmn.broken import broken_count, broken_detail_lines, mark_broken, refuse_broken


@pytest.hookimpl(hookwrapper=True)
def pytest_runtest_makereport(item: Any, call: Any) -> Any:
    outcome = yield
    mark_broken(outcome.get_result(), call)


def pytest_sessionfinish(session: Any, exitstatus: int) -> None:
    refuse_broken(session)


def pytest_terminal_summary(terminalreporter: Any, exitstatus: int, config: Any) -> None:
    stats = terminalreporter.stats
    broken = broken_count(stats)
    for line in result_lines(
        passed=len(stats.get("passed", [])),
        failed=len(stats.get("failed", [])) - broken[0],
        alarms=Alarms(broken=sum(broken)),
        skips=skipped_cases_from(stats.get("skipped", [])),
    ) + broken_detail_lines(stats):
        terminalreporter.write_line(line)
'''

_CASES = '''
import pytest


def test_passes() -> None:
    assert True


def test_fails_on_purpose() -> None:
    assert 1 == 2, "QC_LLM_X: a measured failure"


def test_fails_deliberately() -> None:
    pytest.fail("QC_LLM_X: a deliberate outcome")


def test_crashes() -> None:
    raise OSError("the handle is invalid")


@pytest.fixture(name="broken_setup")
def fixture_broken_setup() -> None:
    raise RuntimeError("setup crashed")


def test_setup_crashes(broken_setup: None) -> None:
    assert broken_setup is None
'''


@allure.epic("AP-Harness-QC")
@allure.feature("Cross-cutting")
class TestMQCBroken:
    """A crash is broken in every output, and the run says nothing was measured."""

    @allure.story("A crash is broken, not failed")
    def MQC_CMN_UNI_112385_a_case_that_crashes_is_broken_and_the_run_exits_3(
        self, tmp_path: Path
    ) -> None:
        """Two crashes count as broken, two failures as failed, and the run exits 3.

        Design: ``harness_test_taxonomy.md`` section 5.1.1.

        Args:
            tmp_path (Path): Where the wired session and its cases are written.

        Returns:
            None
        """
        (tmp_path / "conftest.py").write_text(_CONFTEST, encoding="utf-8")
        (tmp_path / "test_sample.py").write_text(_CASES, encoding="utf-8")
        finished = subprocess.run(
            [sys.executable, "-m", "pytest", "-q", "-p", "no:randomly", "-p", "no:cacheprovider",
             "--rootdir", str(tmp_path), "-c", str(tmp_path / "conftest.py"), str(tmp_path)],
            cwd=_ROOT, capture_output=True, text=True, check=False, timeout=120,
            stdin=subprocess.DEVNULL,
        )
        output = finished.stdout + finished.stderr

        assert "failed: 2" in output and "broken: 2" in output, (
            f"QC_HARNESS_UNANTICIPATED_EXCEPTION: a crash was counted as a failure:\n{output}"
        )
        assert "QC_HARNESS_UNANTICIPATED_EXCEPTION" in output and "OSError" in output, (
            f"the crash was not logged with its code and type:\n{output}"
        )
        assert finished.returncode == 3, (
            f"a run with a broken case exited {finished.returncode}, not 3:\n{output}"
        )

        for conftest in (_ROOT / "conftest.py", _ROOT.parent / "AP-Model-QC" / "conftest.py"):
            if not conftest.is_file():
                continue
            source = conftest.read_text(encoding="utf-8")
            for wired in ("mark_broken(", "refuse_broken(", "broken=sum(broken)",
                          "broken_detail_lines("):
                assert wired in source, f"{conftest} does not call {wired}"
